        d->decode_position = 0;

        d->decoder = 0;

        d->fout = 0; /* initialized with an open file later if necessary */

        d->foreign_metadata = foreign_metadata;

        d->old_clock_t = 0;

        FLAC__ASSERT(!(d->test_only && d->analysis_mode));

        if(!d->test_only) {
                if(0 == strcmp(outfilename, "-")) {
                        d->fout = grabbag__file_get_binary_stdout();
